        border-top: 1px dashed var(--border-color);
      }

      .random-event-item {
        margin: 15px 0;
        padding: 15px;
        background: rgba(255, 235, 205, 0.3);
        border-radius: 5px;
        border-left: 4px solid var(--accent-color);
        box-shadow: 0 2px 5px rgba(0, 0, 0, 0.05);
        transition: all 0.3s ease;
      }

      .random-event-item:hover {
        transform: translateX(5px);
        background: rgba(255, 235, 205, 0.5);
      }

      .event-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 10px;
        padding-bottom: 8px;
        border-bottom: 1px solid rgba(0, 0, 0, 0.1);
      }

      .event-title {
        font-weight: bold;
        font-size: 1.1em;
        color: var(--book-blue);
      }

      .event-location {
        font-size: 0.9em;
        font-style: italic;
        color: var(--text-secondary);
      }

      .event-content {
        font-size: 0.95em;
        line-height: 1.5;
      }

      .event-trigger,
      .event-description,
      .event-guidance,
      .event-judgment,
      .event-result,
      .event-reward {
        margin-bottom: 8px;
        color: #333;
      }

      .event-trigger strong,
      .event-guidance strong,
      .event-judgment strong,
      .event-result strong,
      .event-reward strong {
        color: var(--book-blue);
      }

      .event-completed {
        background-color: rgba(255, 235, 205, 0.5);
        border-left: 4px solid #8bc34a;
      }

      .event-choices {
        margin-top: 15px;
      }

      .event-choice {
        display: block;
        width: 100%;
        padding: 8px 15px;
        margin-bottom: 8px;
        border: 1px solid var(--border-color);
        border-radius: 4px;
        background: rgba(255, 255, 255, 0.5);
        text-align: left;
        transition: all 0.2s ease;
        cursor: pointer;
        font-family: var(--global-font);
      }

      .event-choice:hover {
        background: rgba(255, 255, 255, 0.8);
        transform: translateX(3px);
      }

      .event-choice:last-child {
        margin-bottom: 0;
      }

      .no-events-message {
        padding: 15px;
        font-style: italic;
        color: var(--text-secondary);
        text-align: center;
        background: rgba(255, 255, 255, 0.2);
        border-radius: 5px;
      }
    </style>
  </head>

  <body>
    <div id="app">
      <!-- 装饰花纹背景 -->
      <div class="book-pattern"></div>

      <!-- 竖直装订线 -->
      <div class="binding-thread"></div>

      <!-- 书脊装订线 -->
      <div class="binding-holes">
        <div class="binding-hole"></div>
        <div class="binding-hole"></div>
        <div class="binding-hole"></div>
        <div class="binding-hole"></div>
        <div class="binding-hole"></div>
        <div class="binding-hole"></div>
        <div class="binding-hole"></div>
        <div class="binding-hole"></div>
      </div>

      <!-- 书标题 -->
      <div class="book-title">
        <div class="title-text">金风玉录</div>
        <div class="seal"></div>
      </div>

      <!-- 导航切换按钮 -->
      <button class="nav-toggle" id="navToggle">≡</button>

      <div class="nav-bar">
        <button class="nav-button active" data-panel="content">文之正体</button>
        <button class="nav-button" data-panel="character">性行品第</button>
        <button class="nav-button" data-panel="social">人经伦常</button>
        <button class="nav-button" data-panel="events">机要之节</button>
        <button class="nav-button" data-panel="sect">百工群社</button>
        <button class="nav-button" data-panel="setting">设制布规</button>
      </div>

      <div class="content">
        <!-- 正文面板 -->
        <div class="panel active" id="content">
          <!-- 内容由JavaScript动态生成 -->
        </div>

        <!-- 角色属性面板 -->
        <div class="panel" id="character">
          <!-- 内容由JavaScript动态生成 -->
        </div>

        <!-- 人物关系面板 -->
        <div class="panel" id="social">
          <!-- 内容由JavaScript动态生成 -->
        </div>

        <!-- 关键节点面板 -->
        <div class="panel" id="events">
          <!-- 内容由JavaScript动态生成 -->
        </div>

        <!-- 组织面板 -->
        <div class="panel" id="sect">
          <!-- 内容由JavaScript动态生成 -->
        </div>

        <!-- 设置面板 -->
        <div class="panel" id="setting">
          <h2>界面设置</h2>
          <div class="setting-section">
            <h3>字体设置</h3>
            <div class="setting-item">
              <select id="fontSelect">
                <option value="Huiwen-Fangsong">汇文仿宋</option>
              </select>
            </div>
            <div class="setting-item">
              <label>字体大小：</label>
              <input type="range" id="fontSize" min="10" max="35" value="16" />
              <span id="fontSizeValue">19px</span>
            </div>
          </div>

          <div class="setting-section">
            <h3>窗口设置</h3>
            <div class="setting-item">
              <label>窗口颜色：</label>
              <input type="color" id="windowColor" value="#ffffff" />
              <div class="color-preview" id="windowColorPreview"></div>
            </div>
            <div class="setting-item">
              <label>窗口透明度：</label>
              <input type="range" id="windowOpacity" min="0" max="100" value="81" />
              <span id="opacityValue">95%</span>
            </div>
          </div>
          <div class="setting-section">
            <button class="reset-settings-btn" onclick="resetAndApplySettings()">重置所有设置</button>
          </div>
        </div>
      </div>
    </div>

    <script>
      // 定义游戏文本模板
      let gameText = `<gametext>$1</gametext>`;

      // ==================== 数据提取模块 ====================
      const DataExtractor = {
        extractMainContent(text) {
          const match = text.match(/<maincontent>([\s\S]*?)<\/maincontent>/);
          if (!match) return null;

          try {
            const content = {};
            const lines = match[1].trim().split('\n');

            for (let i = 0; i < lines.length; i++) {
              const line = lines[i].trim();
              if (!line) continue;

              if (line.startsWith('当前章节正文|')) {
                // 提取正文内容，从当前行开始到下一个标签或结束
                let storyContent = [];
                let j = i;

                // 获取第一行的内容（去掉"当前章节正文|"前缀）
                const firstContent = line.substring(line.indexOf('|') + 1).trim();
                if (firstContent) storyContent.push(firstContent);

                // 继续读取后续行，直到遇到新的标签或结束
                j++;
                while (j < lines.length && !lines[j].includes('</maincontent>')) {
                  const content = lines[j].trim();
                  if (content && !content.includes('|')) {
                    storyContent.push(content);
                  }
                  j++;
                }

                // 将所有段落用<p>标签包裹
                content.content = storyContent
                  .filter(p => p.trim())
                  .map(p => `<p>${p.trim()}</p>`)
                  .join('');

                // 保存原始格式的文本（包含"当前章节正文|"）
                content.rawContent = line + '\n' + storyContent.join('\n');

                i = j - 1; // 更新索引
              } else {
                const [key, value] = line.split('|').map(s => s.trim());
                content[
                  key === '当前章节标题'
                    ? 'title'
                    : key === '当前时间'
                    ? 'time'
                    : key === '当前位置'
                    ? 'location'
                    : key === '当前财产'
                    ? 'wealth'
                    : key
                ] = value;
              }
            }

            return content;
          } catch (e) {
            console.error('解析主体内容失败:', e);
            return null;
          }
        },

        extractCharacterInfo(text) {
          const match = text.match(/<characterinfo>([\s\S]*?)<\/characterinfo>/);
          if (!match) return null;

          try {
            const info = {
              basic: {},
              attributes: {},
              values: {},
              tasks: {
                longTerm: [],
                shortTerm: [],
              },
              inventory: {
                assets: {},
                items: [],
                debts: {},
              },
              randomEvents: [], // 添加随机事件数组
            };

            const lines = match[1].trim().split('\n');
            let currentSection = '';

            lines.forEach(line => {
              const [category, key, ...values] = line.split('|').map(s => s.trim());

              switch (category) {
                case '基本信息':
                  info.basic[key] = values[0];
                  break;
                case '属性':
                  info.attributes[key] = parseInt(values[0]);
                  if (values[1]) {
                    info.attributes[`${key}描述`] = values[1];
                  }
                  break;
                case '欲念':
                  info.values[key] = parseInt(values[0]);
                  if (values[1]) {
                    info.values[`${key}描述`] = values[1];
                  }
                  break;
                case '道德':
                  info.values[key] = parseInt(values[0]);
                  if (values[1]) {
                    info.values[`${key}描述`] = values[1];
                  }
                  break;
                case '长期任务':
                  if (key === '标题') currentSection = {};
                  if (key === '标题' || key === '序号' || key === '描述' || key === '目标' || key === '奖励' || key === '进度') {
                    currentSection[key] = key === '进度' ? parseInt(values[0]) : values[0];
                  }
                  if (key === '进度') {
                    info.tasks.longTerm.push({ ...currentSection });
                  }
                  break;
                case '短期任务':
                  if (key === '标题') currentSection = {};
                  if (key === '标题' || key === '序号' || key === '描述' || key === '目标' || key === '奖励' || key === '进度') {
                    currentSection[key] = key === '进度' ? parseInt(values[0]) : values[0];
                  }
                  if (key === '进度') {
                    info.tasks.shortTerm.push({ ...currentSection });
                  }
                  break;
                case '随机事件':
                  if (key === '标题') currentSection = {};
                  if (
                    key === '标题' ||
                    key === '序号' ||
                    key === '触发条件' ||
                    key === '描述' ||
                    key === '行动方向' ||
                    key === '判定' ||
                    key === '结果' ||
                    key === '奖惩' ||
                    key === '进度'
                  ) {
                    currentSection[key] = values[0];
                  }
                  if (key === '选项' && Object.keys(currentSection).length > 0) {
                    if (!currentSection.选项数组) {
                      currentSection.选项数组 = [];
                    }
                    currentSection.选项数组.push(values[0]);
                  }
                  if (key === '结束' && Object.keys(currentSection).length > 0) {
                    info.randomEvents.push({ ...currentSection });
                    currentSection = {};
                  }
                  break;
                case '资产':
                  info.inventory.assets[key] = values[0];
                  break;
                case '物品':
                  if (key === '名称') currentSection = {};
                  currentSection[
                    key === '名称'
                      ? 'name'
                      : key === '数量'
                      ? 'quantity'
                      : key === '描述'
                      ? 'description'
                      : key === '效果'
                      ? 'effect'
                      : key
                  ] = key === '数量' ? parseInt(values[0]) : values[0];
                  if (key === '效果') {
                    info.inventory.items.push({ ...currentSection });
                  }
                  break;
                case '债务':
                  info.inventory.debts[key] = values[0];
                  break;
              }
            });

            // 计算社会等级
            calculateSocialLevel(info);

            return info;
          } catch (e) {
            console.error('解析角色信息失败:', e);
            return null;
          }
        },

        extractSocialInfo(text) {
          const match = text.match(/<socialinfo>([\s\S]*?)<\/socialinfo>/);
          if (!match) return null;

          try {
            const relationships = {};
            let currentType = '';
            let currentCharacter = null;

            const lines = match[1]
              .trim()
              .split('\n')
              .filter(line => !line.trim().startsWith('<!--') && line.trim() !== '');

            lines.forEach(line => {
              const [category, key, value, effect] = line.split('|').map(s => s.trim());

              if (category === '关系类型') {
                if (currentCharacter && currentType) {
                  if (!relationships[currentType]) {
                    relationships[currentType] = [];
                  }
                  relationships[currentType].push(currentCharacter);
                }
                currentType = key;
                currentCharacter = null;
              } else if (category === '关系人物') {
                currentCharacter = {
                  name: key,
                  details: {
                    interactions: [],
                    relations: [],
                    basic: {},
                  },
                  // 确保所有人物都有好感度属性，默认为0
                  favor: 0,
                };
              } else if (currentCharacter) {
                switch (category) {
                  case '人物序号':
                    currentCharacter.index = parseInt(key);
                    break;
                  case '态度':
                    // 记录原始态度，但将在显示时根据好感度计算
                    currentCharacter.originalAttitude = key;
                    break;
                  case '好感度':
                    // 确保好感度在-100到+100范围内
                    currentCharacter.favor = Math.max(-100, Math.min(100, parseInt(key)));
                    break;
                  case '身份':
                    currentCharacter.title = key;
                    break;
                  case '状态':
                    currentCharacter.status = key;
                    break;
                  case '描述':
                    currentCharacter.description = key;
                    break;
                  case '人物关系':
                    try {
                      if (key && value) {
                        currentCharacter.details.relations.push({
                          name: key,
                          description: value,
                        });
                      }
                    } catch (e) {
                      console.error('解析NPC关系JSON时出错:', e);
                    }
                    break;
                  case '基本信息':
                    currentCharacter.details.basic[key] = value;
                    break;
                  case '互动记录':
                    if (currentCharacter.details.interactions.length < 3) {
                      const [date, content] = key.split(':');
                      currentCharacter.details.interactions.push({
                        date: date ? date.trim() : '',
                        content: content ? content.trim() : key,
                      });
                    }
                    break;
                }
              }
            });

            // 添加最后一个角色
            if (currentCharacter && currentType) {
              if (!relationships[currentType]) {
                relationships[currentType] = [];
              }
              relationships[currentType].push(currentCharacter);
            }

            // 计算每个角色的态度
            Object.values(relationships).forEach(characters => {
              characters.forEach(character => {
                // 基于好感度动态计算态度
                character.attitude = calculateAttitudeFromFavor(character.favor);
              });
            });

            return relationships;
          } catch (e) {
            console.error('解析社交信息失败:', e);
            return null;
          }
        },

        extractTimelineInfo(text) {
          const match = text.match(/<timelineinfo>([\s\S]*?)<\/timelineinfo>/);
          if (!match) return null;

          try {
            const events = [];
            let currentEvent = {};
            let eventIndex = 0;

            const lines = match[1].trim().split('\n');
            lines.forEach(line => {
              const [category, key, value] = line.split('|').map(s => s.trim());

              if (category.startsWith('事件')) {
                if (key === '日期') {
                  if (Object.keys(currentEvent).length > 0) {
                    events.push({ ...currentEvent });
                  }
                  eventIndex++;
                  currentEvent = {
                    index: eventIndex,
                  };
                }

                switch (key) {
                  case '日期':
                    currentEvent.date = value;
                    break;
                  case '标题':
                    currentEvent.title = value;
                    break;
                  case '描述':
                    currentEvent.description = value;
                    break;
                  case '当前':
                    currentEvent.current = value === 'true';
                    break;
                }
              }
            });

            // 确保添加最后一个事件
            if (Object.keys(currentEvent).length > 0) {
              events.push(currentEvent);
            }

            return events;
          } catch (e) {
            console.error('解析关键节点失败:', e);
            return null;
          }
        },

        extractSectInfo(text) {
          const match = text.match(/<sectinfo>([\s\S]*?)<\/sectinfo>/);
          if (!match) return null;

          try {
            const organizations = {
              official: [],
              civilian: [],
            };

            let currentType = '';
            let currentOrg = null;

            const lines = match[1].trim().split('\n');
            lines.forEach(line => {
              const [category, ...values] = line.split('|').map(s => s.trim());

              switch (category) {
                case '官方组织':
                  if (currentOrg && values[0] === '名称') {
                    if (!organizations.official) organizations.official = [];
                    organizations.official.push({ ...currentOrg });
                  }
                  if (values[0] === '名称') {
                    currentOrg = {
                      name: values[1],
                      members: [],
                    };
                  } else if (currentOrg) {
                    if (values[0] === '类型') {
                      currentOrg.type = values[1];
                    } else if (values[0] === '描述') {
                      currentOrg.description = values[1];
                    } else if (values[0] === '影响力') {
                      currentOrg.influence = parseInt(values[1]);
                    } else if (values[0] === '态度') {
                      currentOrg.attitude = values[1];
                    } else if (values[0] === '成员') {
                      try {
                        // 尝试将成员信息添加到组织中
                        if (values[1] && values[2]) {
                          currentOrg.members.push({
                            name: values[1],
                            position: values[2],
                          });
                        }
                      } catch (e) {
                        console.error('解析组织成员信息失败:', e);
                      }
                    }
                  }
                  break;
                case '民间组织':
                  if (currentOrg && values[0] === '名称') {
                    if (!organizations.civilian) organizations.civilian = [];
                    organizations.civilian.push({ ...currentOrg });
                  }
                  if (values[0] === '名称') {
                    currentOrg = {
                      name: values[1],
                      members: [],
                    };
                  } else if (currentOrg) {
                    if (values[0] === '类型') {
                      currentOrg.type = values[1];
                    } else if (values[0] === '描述') {
                      currentOrg.description = values[1];
                    } else if (values[0] === '影响力') {
                      currentOrg.influence = parseInt(values[1]);
                    } else if (values[0] === '态度') {
                      currentOrg.attitude = values[1];
                    } else if (values[0] === '成员') {
                      try {
                        // 尝试将成员信息添加到组织中
                        if (values[1] && values[2]) {
                          currentOrg.members.push({
                            name: values[1],
                            position: values[2],
                          });
                        }
                      } catch (e) {
                        console.error('解析组织成员信息失败:', e);
                      }
                    }
                  }
                  break;
              }
            });

            // 确保添加最后一个组织
            if (currentOrg) {
              if (currentType === '官方组织') {
                if (!organizations.official) organizations.official = [];
                organizations.official.push(currentOrg);
              } else if (currentType === '民间组织') {
                if (!organizations.civilian) organizations.civilian = [];
                organizations.civilian.push(currentOrg);
              }
            }

            return organizations;
          } catch (e) {
            console.error('解析组织信息失败:', e);
            return null;
          }
        },
      };

      // ==================== UI更新模块 ====================
      const UIUpdater = {
        updateMainContent(content) {
          if (!content) return;

          const contentPanel = document.querySelector('#content');
          if (!contentPanel) return;

          contentPanel.innerHTML = `
        <div class="status-bar">
            <div class="status-item">
                <span class="status-label">当前时间</span>
                <span class="status-value">${content.time}</span>
            </div>
            <div class="status-item">
                <span class="status-label">当前位置</span>
                <span class="status-value">${content.location}</span>
            </div>
            <div class="status-item">
                <span class="status-label">财产</span>
                <span class="status-value">${content.wealth}</span>
            </div>
        </div>
        <h2>${content.title}</h2>
        <div class="story-content">${content.content}</div>
    `;
        },

        updateCharacterInfo(info) {
          if (!info) return;

          const characterPanel = document.querySelector('#character');
          if (!characterPanel) return;

          // 准备欲念和道德数据
          const allValues = Object.entries(info.values).filter(([key]) => !key.includes('描述'));
          const desireValues = allValues.filter(([key]) => ['权欲', '财欲', '色欲', '名欲'].includes(key));
          const moralValues = allValues.filter(([key]) => ['仁德', '义气', '礼节', '信誉'].includes(key));

          // 计算社会等级（如果还没计算）
          if (!info.socialLevel) {
            calculateSocialLevel(info);
          }

          characterPanel.innerHTML = `
            <h2>角色属性</h2>
            <div class="info-section">
                <div class="basic-info">
                    <h3>基本信息</h3>
                    <p><strong>姓名：</strong>${info.basic.姓名 || '未知'}</p>
                    <p><strong>年龄：</strong>${info.basic.年龄 || '未知'}</p>
                    <p><strong>性别：</strong>${info.basic.性别 || '未知'}</p>
                    <p><strong>背景：</strong>${info.basic.背景 || '未知'}</p>
                    <div class="social-level">
                        社会等级：<span class="social-level-value">${info.socialLevel || '1'}</span>
                    </div>
                </div>

                <div class="attributes-section">
                    <h3>角色属性</h3>
                    <div class="radar-chart">
                        <canvas id="attributesChart" width="300" height="300"></canvas>
                    </div>
                    <div class="attributes-list">
                        ${Object.entries(info.attributes)
                          .filter(([key]) => !key.includes('描述'))
                          .map(([name, value]) => {
                            const description = info.attributes[`${name}描述`] || '';
                            return `
                            <div class="attribute-item">
                                <div class="attribute-name">${name}</div>
                                <div class="attribute-value">${value}</div>
                                ${description ? `<div class="attribute-description">${description}</div>` : ''}
                            </div>
                        `;
                          })
                          .join('')}
                    </div>
                </div>

                <div class="values-section">
                    <h3>欲念与道德</h3>
                    <div class="values-radar-chart">
                        <canvas id="valuesRadarChart" width="300" height="300"></canvas>
                    </div>
                </div>

                <div class="tasks-section">
                    <h3>任务</h3>
                    <h4>长期任务</h4>
                    <div id="long-term-tasks">
                        ${
                          info.tasks.longTerm.length > 0
                            ? info.tasks.longTerm
                                .map(
                                  (task, index) => `
                              <div class="task-item ${
                                task.进度 === 100 ? 'task-completed' : ''
                              }" data-task-id="longTerm-${index}">
                                  <div class="task-header">
                                      <span class="task-title">${task.标题}</span>
                                      <span class="task-index">${task.序号}</span>
                                      <span class="task-type long-term">长期</span>
                                  </div>
                                  <div class="task-content">
                                      <div class="task-description">${task.描述}</div>
