      // ==================== 图形绘制模块 ====================
      const GraphicsRenderer = {
        drawAttributesRadarChart(attributes) {
          const canvas = document.getElementById('attributesChart');
          if (!canvas || !attributes) return;

          const ctx = canvas.getContext('2d');
          const centerX = canvas.width / 2;
          const centerY = canvas.height / 2;
          const radius = 120;

          // 清空画布
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          // 获取属性数据并归一化
          const attributeNames = Object.keys(attributes).filter(key => !key.includes('描述'));
          const attributeValues = attributeNames.map(name => attributes[name]);
          const sides = attributeNames.length;

          // 找出最大值用于归一化
          const maxValue = Math.max(...attributeValues, 100);

          // 绘制背景网格
          for (let gridLevel = 1; gridLevel <= 5; gridLevel++) {
            ctx.beginPath();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.1)';

            for (let i = 0; i < sides; i++) {
              const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;
              const r = (radius * gridLevel) / 5;
              const x = centerX + r * Math.cos(angle);
              const y = centerY + r * Math.sin(angle);

              if (i === 0) {
                ctx.moveTo(x, y);
              } else {
                ctx.lineTo(x, y);
              }
            }

            ctx.closePath();
            ctx.stroke();

            // 添加刻度值标注
            const scaleValue = Math.round((maxValue * gridLevel) / 5);
            ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
            ctx.font = '12px var(--global-font)';
            ctx.fillText(scaleValue.toString(), centerX + 5, centerY - (radius * gridLevel) / 5);
          }

          // 绘制属性轴线和名称
          for (let i = 0; i < sides; i++) {
            const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;

            // 绘制轴线
            ctx.beginPath();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.2)';
            ctx.moveTo(centerX, centerY);
            ctx.lineTo(centerX + radius * Math.cos(angle), centerY + radius * Math.sin(angle));
            ctx.stroke();

            // 绘制属性名称
            ctx.fillStyle = '#333';
            ctx.font = '14px var(--global-font)';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';

            const textRadius = radius + 20;
            const textX = centerX + textRadius * Math.cos(angle);
            const textY = centerY + textRadius * Math.sin(angle);

            ctx.fillText(`${attributeNames[i]} (${attributeValues[i]})`, textX, textY);
          }

          // 绘制数值区域
          ctx.beginPath();
          ctx.fillStyle = 'rgba(139, 69, 19, 0.2)';
          ctx.strokeStyle = 'rgba(139, 69, 19, 0.8)';
          ctx.lineWidth = 2;

          for (let i = 0; i < sides; i++) {
            const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;
            const normalizedValue = attributeValues[i] / maxValue;
            const r = radius * normalizedValue;
            const x = centerX + r * Math.cos(angle);
            const y = centerY + r * Math.sin(angle);

            if (i === 0) {
              ctx.moveTo(x, y);
            } else {
              ctx.lineTo(x, y);
            }
          }

          ctx.closePath();
          ctx.fill();
          ctx.stroke();

          // 绘制数值点
          for (let i = 0; i < sides; i++) {
            const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;
            const normalizedValue = attributeValues[i] / maxValue;
            const r = radius * normalizedValue;
            const x = centerX + r * Math.cos(angle);
            const y = centerY + r * Math.sin(angle);

            ctx.beginPath();
            ctx.fillStyle = '#8B4513';
            ctx.arc(x, y, 4, 0, 2 * Math.PI);
            ctx.fill();
          }
        },

        drawValuesRadarChart(values) {
          const canvas = document.getElementById('valuesRadarChart');
          if (!canvas || !values) return;

          const ctx = canvas.getContext('2d');
          const centerX = canvas.width / 2;
          const centerY = canvas.height / 2;
          const radius = 120;

          // 清空画布
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          // 筛选出欲念和道德属性
          const desireNames = ['权欲', '财欲', '色欲', '名欲'].filter(name => values[name] !== undefined);
          const moralNames = ['仁德', '义气', '礼节', '信誉'].filter(name => values[name] !== undefined);

          const desireValues = desireNames.map(name => values[name]);
          const moralValues = moralNames.map(name => values[name]);

          const sides = desireNames.length + moralNames.length;
          const allNames = [...desireNames, ...moralNames];
          const allValues = [...desireValues, ...moralValues];

          // 找出最大值用于归一化
          const maxValue = Math.max(...allValues, 100);

          // 绘制标题
          ctx.fillStyle = '#333';
          ctx.font = 'bold 16px var(--global-font)';
          ctx.textAlign = 'center';
          ctx.fillText('欲念与道德雷达图', centerX, 20);

          // 绘制背景网格
          for (let gridLevel = 1; gridLevel <= 5; gridLevel++) {
            ctx.beginPath();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.1)';

            for (let i = 0; i < sides; i++) {
              const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;
              const r = (radius * gridLevel) / 5;
              const x = centerX + r * Math.cos(angle);
              const y = centerY + r * Math.sin(angle);

              if (i === 0) {
                ctx.moveTo(x, y);
              } else {
                ctx.lineTo(x, y);
              }
            }

            ctx.closePath();
            ctx.stroke();

            // 添加刻度值标注
            const scaleValue = Math.round((maxValue * gridLevel) / 5);
            ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
            ctx.font = '12px var(--global-font)';
            ctx.fillText(scaleValue.toString(), centerX + 5, centerY - (radius * gridLevel) / 5);
          }

          // 绘制属性轴线和名称
          for (let i = 0; i < sides; i++) {
            const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;

            // 绘制轴线
            ctx.beginPath();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.2)';
            ctx.moveTo(centerX, centerY);
            ctx.lineTo(centerX + radius * Math.cos(angle), centerY + radius * Math.sin(angle));
            ctx.stroke();

            // 绘制属性名称
            ctx.fillStyle = i < desireNames.length ? '#B71C1C' : '#1A5276';
            ctx.font = '14px var(--global-font)';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';

            const textRadius = radius + 20;
            const textX = centerX + textRadius * Math.cos(angle);
            const textY = centerY + textRadius * Math.sin(angle);

            ctx.fillText(`${allNames[i]} (${allValues[i]})`, textX, textY);
          }

          // 绘制欲念数值区域
          if (desireValues.length > 0) {
            ctx.beginPath();
            ctx.fillStyle = 'rgba(183, 28, 28, 0.2)';
            ctx.strokeStyle = 'rgba(183, 28, 28, 0.8)';
            ctx.lineWidth = 2;

            for (let i = 0; i < desireNames.length; i++) {
              const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;
              const normalizedValue = desireValues[i] / maxValue;
              const r = radius * normalizedValue;
              const x = centerX + r * Math.cos(angle);
              const y = centerY + r * Math.sin(angle);

              if (i === 0) {
                ctx.moveTo(x, y);
              } else {
                ctx.lineTo(x, y);
              }
            }

            ctx.closePath();
            ctx.fill();
            ctx.stroke();

            // 绘制欲念数值点
            for (let i = 0; i < desireNames.length; i++) {
              const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;
              const normalizedValue = desireValues[i] / maxValue;
              const r = radius * normalizedValue;
              const x = centerX + r * Math.cos(angle);
              const y = centerY + r * Math.sin(angle);

              ctx.beginPath();
              ctx.fillStyle = '#B71C1C';
              ctx.arc(x, y, 4, 0, 2 * Math.PI);
              ctx.fill();
            }
          }

          // 绘制道德数值区域
          if (moralValues.length > 0) {
            ctx.beginPath();
            ctx.fillStyle = 'rgba(26, 82, 118, 0.2)';
            ctx.strokeStyle = 'rgba(26, 82, 118, 0.8)';
            ctx.lineWidth = 2;

            for (let i = 0; i < moralNames.length; i++) {
              const idx = i + desireNames.length;
              const angle = (idx * 2 * Math.PI) / sides - Math.PI / 2;
              const normalizedValue = moralValues[i] / maxValue;
              const r = radius * normalizedValue;
              const x = centerX + r * Math.cos(angle);
              const y = centerY + r * Math.sin(angle);

              if (i === 0) {
                ctx.moveTo(x, y);
              } else {
                ctx.lineTo(x, y);
              }
            }

            ctx.closePath();
            ctx.fill();
            ctx.stroke();

            // 绘制道德数值点
            for (let i = 0; i < moralNames.length; i++) {
              const idx = i + desireNames.length;
              const angle = (idx * 2 * Math.PI) / sides - Math.PI / 2;
              const normalizedValue = moralValues[i] / maxValue;
              const r = radius * normalizedValue;
              const x = centerX + r * Math.cos(angle);
              const y = centerY + r * Math.sin(angle);

              ctx.beginPath();
              ctx.fillStyle = '#1A5276';
              ctx.arc(x, y, 4, 0, 2 * Math.PI);
              ctx.fill();
            }
          }

          // 添加图例
          const legendY = canvas.height - 30;

          // 欲念图例
          ctx.beginPath();
          ctx.fillStyle = 'rgba(183, 28, 28, 0.2)';
          ctx.strokeStyle = 'rgba(183, 28, 28, 0.8)';
          ctx.lineWidth = 1;
          ctx.rect(centerX - 100, legendY, 15, 15);
          ctx.fill();
          ctx.stroke();

          ctx.fillStyle = '#333';
          ctx.textAlign = 'left';
          ctx.font = '14px var(--global-font)';
          ctx.fillText('欲念', centerX - 80, legendY + 12);

          // 道德图例
          ctx.beginPath();
          ctx.fillStyle = 'rgba(26, 82, 118, 0.2)';
          ctx.strokeStyle = 'rgba(26, 82, 118, 0.8)';
          ctx.lineWidth = 1;
          ctx.rect(centerX + 20, legendY, 15, 15);
          ctx.fill();
          ctx.stroke();

          ctx.fillStyle = '#333';
          ctx.textAlign = 'left';
          ctx.font = '14px var(--global-font)';
          ctx.fillText('道德', centerX + 40, legendY + 12);
        },
      };

      // ==================== 初始化代码 ====================
      document.addEventListener('DOMContentLoaded', function () {
        initializeUI();
        bindEventListeners();

        if (typeof gameText !== 'undefined') {
          processGameText(gameText);
        }
      });

      // 主处理函数
      function processGameText(text) {
        const mainContent = DataExtractor.extractMainContent(text);
        const characterInfo = DataExtractor.extractCharacterInfo(text);
        const socialInfo = DataExtractor.extractSocialInfo(text);
        const timelineInfo = DataExtractor.extractTimelineInfo(text);
        const sectInfo = DataExtractor.extractSectInfo(text);

        UIUpdater.updateMainContent(mainContent);
        if (characterInfo && characterInfo.attributes) {
          GraphicsRenderer.drawAttributesRadarChart(characterInfo.attributes);
        }
        UIUpdater.updateCharacterInfo(characterInfo);
        UIUpdater.updateSocialInfo(socialInfo);
        UIUpdater.updateTimelineInfo(timelineInfo);
        UIUpdater.updateSectInfo(sectInfo);
      }

      // 初始化UI
      function initializeUI() {
        // 导航栏切换功能
        const navToggle = document.getElementById('navToggle');
        const navBar = document.querySelector('.nav-bar');

        navToggle.addEventListener('click', function () {
          navBar.classList.toggle('show');
        });

        // 点击页面其他区域关闭导航栏
        document.addEventListener('click', function (event) {
          if (!navBar.contains(event.target) && event.target !== navToggle) {
            navBar.classList.remove('show');
          }
        });

        // 点击导航按钮后自动关闭导航栏
        document.querySelectorAll('.nav-button').forEach(button => {
          button.addEventListener('click', () => {
            document.querySelectorAll('.nav-button').forEach(btn => btn.classList.remove('active'));
            document.querySelectorAll('.panel').forEach(panel => panel.classList.remove('active'));

            button.classList.add('active');
            const panelId = button.getAttribute('data-panel');
            document.getElementById(panelId).classList.add('active');

            // 关闭导航栏
            navBar.classList.remove('show');
          });
        });

        // 初始化设置面板
        initializeSettings();
      }

      // 绑定全局事件监听器
      function bindEventListeners() {
        // 窗口大小改变时重绘雷达图
        window.addEventListener('resize', () => {
          const characterInfo = DataExtractor.extractCharacterInfo(gameText);
          if (characterInfo) {
            GraphicsRenderer.drawAttributesRadarChart(characterInfo.attributes);
          }
        });
      }

      // 初始化设置
      function initializeSettings() {
        // 字体设置已经被固定为汇文仿宋，移除选择器
        const fontSelect = document.getElementById('fontSelect');
        if (fontSelect) {
          fontSelect.parentNode.innerHTML = '<div style="padding: 10px;">字体: 汇文仿宋（固定）</div>';
        }

        // 字体大小
        const fontSizeSlider = document.getElementById('fontSize');
        const fontSizeValue = document.getElementById('fontSizeValue');
        if (fontSizeSlider && fontSizeValue) {
          // 设置保存的字体大小
          const savedSettings = loadSettings();
          if (savedSettings.fontSize) {
            fontSizeSlider.value = savedSettings.fontSize;
            fontSizeValue.textContent = savedSettings.fontSize + 'px';
            document.querySelectorAll('.panel').forEach(panel => {
              panel.style.fontSize = savedSettings.fontSize + 'px';
            });
          }

          fontSizeSlider.addEventListener('input', function () {
            const size = this.value;
            document.querySelectorAll('.panel').forEach(panel => {
              panel.style.fontSize = size + 'px';
            });
            fontSizeValue.textContent = size + 'px';
            saveSettings('fontSize', size);
          });
        }

        // 窗口颜色
        const windowColorInput = document.getElementById('windowColor');
        const windowColorPreview = document.getElementById('windowColorPreview');
        if (windowColorInput && windowColorPreview) {
          // 设置保存的窗口颜色
          const savedSettings = loadSettings();
          if (savedSettings.windowColor) {
            windowColorInput.value = savedSettings.windowColor;
            windowColorPreview.style.backgroundColor = savedSettings.windowColor;
            document.querySelectorAll('.panel').forEach(panel => {
              panel.style.backgroundColor = savedSettings.windowColor;
            });
          }

          windowColorInput.addEventListener('input', function () {
            const color = this.value;
            document.querySelectorAll('.panel').forEach(panel => {
              panel.style.backgroundColor = color;
            });
            windowColorPreview.style.backgroundColor = color;
            saveSettings('windowColor', color);
          });
        }

        // 窗口透明度
        const opacitySlider = document.getElementById('windowOpacity');
        const opacityValue = document.getElementById('opacityValue');
        if (opacitySlider && opacityValue) {
          // 设置保存的透明度
          const savedSettings = loadSettings();
          if (savedSettings.opacity) {
            opacitySlider.value = savedSettings.opacity;
            opacityValue.textContent = savedSettings.opacity + '%';
            document.querySelectorAll('.panel').forEach(panel => {
              panel.style.opacity = savedSettings.opacity / 100;
            });
          }

          opacitySlider.addEventListener('input', function () {
            const opacity = this.value;
            document.querySelectorAll('.panel').forEach(panel => {
              panel.style.opacity = opacity / 100;
            });
            opacityValue.textContent = opacity + '%';
            saveSettings('opacity', opacity);
          });
        }
      }

      // 添加保存设置的函数
      function saveSettings(key, value) {
        try {
          let settings = JSON.parse(localStorage.getItem('userSettings') || '{}');
          settings[key] = value;
          localStorage.setItem('userSettings', JSON.stringify(settings));
        } catch (e) {
          console.error('保存设置失败:', e);
        }
      }

      // 添加加载设置的函数
      function loadSettings() {
        try {
          const settings = JSON.parse(localStorage.getItem('userSettings') || '{}');
          return settings;
        } catch (e) {
          console.error('加载设置失败:', e);
          return {};
        }
      }

      // 添加重置设置的函数
      function resetSettings() {
        const defaultSettings = {
          font: 'chengrongguangke',
          fontSize: '16',
          windowColor: '#ffffff',
          opacity: '81',
        };

        localStorage.setItem('userSettings', JSON.stringify(defaultSettings));
        return defaultSettings;
      }
      function resetAndApplySettings() {
        if (confirm('确定要重置所有设置吗？')) {
          const defaultSettings = resetSettings();

          // 重新加载页面以应用默认设置
          location.reload();
        }
      }

      let archiveSaved = false;

      // 完全重写applyTaskReward函数，使用更可靠的方式查找和更新DOM元素
      function applyTaskReward(rewardText, characterInfo) {
        // 解析奖励文本，格式通常为"属性名+数值"，如"武力+5，智力+3"
        const rewards = rewardText.split('，'); // 使用中文逗号分割

        rewards.forEach(reward => {
          // 尝试匹配"属性名+数值"的模式
          const match = reward.match(/(.+?)([+-]\d+)/);
          if (match) {
            const attributeName = match[1].trim();
            const changeValue = parseInt(match[2]);

            // 更新对应的属性值
            if (characterInfo.attributes[attributeName] !== undefined) {
              // 更新数据模型
              characterInfo.attributes[attributeName] += changeValue;

              // 直接通过遍历DOM元素查找匹配的属性名元素，避免使用自定义选择器
              const attributeItems = document.querySelectorAll('.attribute-item');
              attributeItems.forEach(item => {
                const nameElement = item.querySelector('.attribute-name');
                if (nameElement && nameElement.textContent === attributeName) {
                  const valueElement = item.querySelector('.attribute-value');
                  if (valueElement) {
                    // 更新DOM显示
                    valueElement.textContent = characterInfo.attributes[attributeName];
                  }
                }
              });
            }
            // 更新values中的值（如欲念、道德等）
            else if (characterInfo.values[attributeName] !== undefined) {
              characterInfo.values[attributeName] += changeValue;
            }
          }
        });

        // 重绘属性雷达图以反映变化
        if (window.GraphicsRenderer) {
          GraphicsRenderer.drawAttributesRadarChart(characterInfo.attributes);
          GraphicsRenderer.drawValuesRadarChart(characterInfo.values);
        }
      }

      // 添加计算社会等级的函数
      function calculateSocialLevel(characterInfo) {
        if (!characterInfo || !characterInfo.attributes) return;

        // 计算所有属性的平均值
        const attributeValues = Object.entries(characterInfo.attributes)
          .filter(([key]) => !key.includes('描述'))
          .map(([_, value]) => value);

        const averageAttribute =
          attributeValues.length > 0
            ? attributeValues.reduce((sum, value) => sum + value, 0) / attributeValues.length
            : 0;

        // 根据平均属性值确定社会等级
        let socialLevel = 1;
        if (averageAttribute >= 90) socialLevel = 8;
        else if (averageAttribute >= 60) socialLevel = 7;
        else if (averageAttribute >= 40) socialLevel = 6;
        else if (averageAttribute >= 27) socialLevel = 5;
        else if (averageAttribute >= 18) socialLevel = 4;
        else if (averageAttribute >= 12) socialLevel = 3;
        else if (averageAttribute >= 8) socialLevel = 2;

        // 存储社会等级
        characterInfo.socialLevel = socialLevel;
        characterInfo.averageAttribute = Math.round(averageAttribute * 10) / 10; // 保留一位小数

        return socialLevel;
      }

      // 添加基于好感度计算态度的函数
      function calculateAttitudeFromFavor(favor) {
        // 确保好感度在-100到+100范围内
        const normalizedFavor = Math.max(-100, Math.min(100, favor));

        // 根据好感度范围确定态度
        if (normalizedFavor <= -70) return '深仇大恨';
        if (normalizedFavor <= -40) return '敌对';
        if (normalizedFavor <= -10) return '不友好';
        if (normalizedFavor < 10) return '中立';
        if (normalizedFavor < 40) return '友善';
        if (normalizedFavor < 70) return '信任';
        return '亲密';
      }

      // 添加获取态度对应CSS类的函数
      function getAttitudeClass(attitude) {
        switch (attitude) {
          case '深仇大恨':
            return 'attitude-hostile';
          case '敌对':
            return 'attitude-hostile';
          case '不友好':
            return 'attitude-unfriendly';
          case '中立':
            return 'attitude-neutral';
          case '友善':
            return 'attitude-friendly';
          case '信任':
            return 'attitude-trusted';
          case '亲密':
            return 'attitude-devoted';
          default:
            return 'attitude-neutral';
        }
      }
      // 添加判断是否有随机事件的函数
      function hasRandomEvent(info) {
        // 检查是否有随机事件数据
        if (!info.randomEvents || info.randomEvents.length === 0) {
          return false;
        }
        // 随机生成一个概率（30%几率触发）
        return Math.random() < 0.3 ? true : false;
      }
    </script>
