            </div>
            <div class="step active" data-step="1">
              <div class="step-circle">一</div>
              <div class="step-title">性别选择</div>
            </div>
            <div class="step" data-step="2">
              <div class="step-circle">二</div>
              <div class="step-title">身份选择</div>
            </div>
            <div class="step" data-step="3">
              <div class="step-circle">三</div>
              <div class="step-title">经历与特长</div>
            </div>
            <div class="step" data-step="4">
              <div class="step-circle">四</div>
              <div class="step-title">角色确认</div>
