        // 初始化导航按钮
        function initializeNavigationButtons() {
          // 获取所有步骤和步骤内容元素
          const steps = document.querySelectorAll('.step');
          const stepContents = document.querySelectorAll('.step-content');
          const stepsProgress = document.getElementById('steps-progress');

          // 下一步按钮事件绑定
          document.getElementById('btn-next-1').addEventListener('click', () => navigateToStep(2));
          document.getElementById('btn-next-2').addEventListener('click', () => navigateToStep(3));
          document.getElementById('btn-next-3').addEventListener('click', () => navigateToStep(4));

          // 上一步按钮事件绑定
          document.getElementById('btn-prev-2').addEventListener('click', () => navigateToStep(1));
          document.getElementById('btn-prev-3').addEventListener('click', () => navigateToStep(2));
          document.getElementById('btn-prev-4').addEventListener('click', () => navigateToStep(3));

          // 步骤导航函数
          function navigateToStep(step) {
            if (step < 1 || step > 4) return;

            // 更新当前步骤
            currentStep = step;

            // 更新步骤指示器
            updateStepIndicators();

            // 显示当前步骤内容
            showCurrentStep();

            // 如果是步骤4，更新预览
            if (currentStep === 4) {
              updatePreview();
            }

            // 平滑滚动到顶部
            window.scrollTo({ top: 0, behavior: 'smooth' });
          }

          // 更新步骤指示器
          function updateStepIndicators() {
            // 更新步骤圆圈状态
            steps.forEach((step, index) => {
              const stepNumber = index + 1;

              if (stepNumber === currentStep) {
                step.classList.add('active');
                step.classList.remove('completed');
              } else if (stepNumber < currentStep) {
                step.classList.remove('active');
                step.classList.add('completed');
              } else {
                step.classList.remove('active');
                step.classList.remove('completed');
              }
            });

            // 更新进度条
            const progressWidth = ((currentStep - 1) / 3) * 100;
            stepsProgress.style.width = `${progressWidth}%`;
          }

          // 显示当前步骤内容
          function showCurrentStep() {
            // 隐藏所有步骤内容
            stepContents.forEach(content => content.classList.remove('active'));

            // 显示当前步骤内容
            document.getElementById(`step-${currentStep}`).classList.add('active');
          }
        }

