          experienceOptions.forEach(option => {
            const optionGender = option.getAttribute('data-gender');
            const optionIdentities = option.getAttribute('data-identity').split(',');

            // 显示条件：全部都可见，或者性别匹配且身份匹配或全部可见
            const shouldShow =
              (optionGender === 'all' && optionIdentities.includes('all')) ||
              ((optionGender === 'all' || optionGender === selectedGender) &&
                (optionIdentities.includes('all') || optionIdentities.includes(selectedIdentity)));

            if (shouldShow) {
              option.classList.remove('hidden');
            } else {
              option.classList.add('hidden');
              // 如果当前选中的选项被隐藏，则清除选中状态
              if (option.classList.contains('selected')) {
                option.classList.remove('selected');
                gameData.player.experience = '';
