        .timeline-event {
          padding-left: 20px;
        }

        .setting-item {
          flex-direction: column;
          align-items: flex-start;
        }

        .setting-label {
          margin-bottom: 5px;
        }

        .setting-control {
          width: 100%;
        }
      }

      /* 小型手机设备 - 屏幕宽度小于 480px */
      @media screen and (max-width: 480px) {
