        .timeline-event::before {
          width: 8px;
          height: 8px;
        }

        .timeline-content {
          padding: 10px;
        }

        .search-box input {
          width: 100%;
        }

        .filter-controls {
          width: 100%;
        }

        .filter-controls select {
          width: 100%;
        }
      }

      /* 处理横屏模式 */
      @media screen and (max-height: 600px) and (orientation: landscape) {
        .nav-bar {
          position: static;
          margin-bottom: 10px;
        }

        .content {
          margin-top: 10px;
        }

        .panel {
          max-height: none;
        }

        .radar-chart {
          width: 200px;
          height: 200px;
        }
