        background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200" viewBox="0 0 200 200"><path d="M40,40 Q50,20 60,40 Q70,60 80,40 Q90,20 100,40 Q110,60 120,40 Q130,20 140,40 Q150,60 160,40" fill="none" stroke="rgba(180,140,100,0.2)" stroke-width="1" transform="rotate(90, 100, 100)"/></svg>');
