    <script>
      // 定义游戏文本模板
      let gameText = `<gametext>$1</gametext>`;

      // ==================== 数据提取模块 ====================
      const DataExtractor = {
        extractMainContent(text) {
          const match = text.match(/<maincontent>([\s\S]*?)<\/maincontent>/);
          if (!match) return null;

          try {
            const content = {};
            const lines = match[1].trim().split('\n');

            for (let i = 0; i < lines.length; i++) {
              const line = lines[i].trim();
              if (!line) continue;

              if (line.startsWith('当前章节正文|')) {
                // 提取正文内容，从当前行开始到下一个标签或结束
                let storyContent = [];
                let j = i;

                // 获取第一行的内容（去掉"当前章节正文|"前缀）
                const firstContent = line.substring(line.indexOf('|') + 1).trim();
                if (firstContent) storyContent.push(firstContent);

                // 继续读取后续行，直到遇到新的标签或结束
                j++;
                while (j < lines.length && !lines[j].includes('</maincontent>')) {
                  const content = lines[j].trim();
                  if (content && !content.includes('|')) {
                    storyContent.push(content);
                  }
                  j++;
                }

                // 将所有段落用<p>标签包裹
                content.content = storyContent
                  .filter(p => p.trim())
                  .map(p => `<p>${p.trim()}</p>`)
                  .join('');

                // 保存原始格式的文本（包含"当前章节正文|"）
                content.rawContent = line + '\n' + storyContent.join('\n');

                i = j - 1; // 更新索引
              } else {
                const [key, value] = line.split('|').map(s => s.trim());
                content[
                  key === '当前章节标题'
                    ? 'title'
                    : key === '当前时间'
                    ? 'time'
                    : key === '当前位置'
                    ? 'location'
                    : key === '当前财产'
                    ? 'wealth'
                    : key
                ] = value;
              }
            }

            return content;
          } catch (e) {
            console.error('解析主体内容失败:', e);
            return null;
          }
        },

        extractCharacterInfo(text) {
          const match = text.match(/<characterinfo>([\s\S]*?)<\/characterinfo>/);
          if (!match) return null;

          try {
            const info = {
              basic: {},
              attributes: {},
              values: {},
              tasks: {
                longTerm: [],
                shortTerm: [],
              },
              inventory: {
                assets: {},
                items: [],
                debts: {},
              },
              randomEvents: [], // 添加随机事件数组
            };

            const lines = match[1].trim().split('\n');
            let currentSection = '';

            lines.forEach(line => {
              const [category, key, ...values] = line.split('|').map(s => s.trim());

              switch (category) {
                case '基本信息':
                  info.basic[key] = values[0];
                  break;
                case '属性':
                  info.attributes[key] = parseInt(values[0]);
                  if (values[1]) {
                    info.attributes[`${key}描述`] = values[1];
                  }
                  break;
                case '欲念':
                  info.values[key] = parseInt(values[0]);
                  if (values[1]) {
                    info.values[`${key}描述`] = values[1];
                  }
                  break;
                case '道德':
                  info.values[key] = parseInt(values[0]);
                  if (values[1]) {
                    info.values[`${key}描述`] = values[1];
                  }
                  break;
                case '长期任务':
                  if (key === '标题') currentSection = {};
                  if (key === '标题' || key === '序号' || key === '描述' || key === '目标' || key === '奖励' || key === '进度') {
                    currentSection[key] = key === '进度' ? parseInt(values[0]) : values[0];
                  }
                  if (key === '进度') {
                    info.tasks.longTerm.push({ ...currentSection });
                  }
                  break;
                case '短期任务':
                  if (key === '标题') currentSection = {};
                  if (key === '标题' || key === '序号' || key === '描述' || key === '目标' || key === '奖励' || key === '进度') {
                    currentSection[key] = key === '进度' ? parseInt(values[0]) : values[0];
                  }
                  if (key === '进度') {
                    info.tasks.shortTerm.push({ ...currentSection });
                  }
                  break;
                case '随机事件':
                  if (key === '标题') currentSection = {};
                  if (
                    key === '标题' ||
                    key === '序号' ||
                    key === '触发条件' ||
                    key === '描述' ||
                    key === '行动方向' ||
                    key === '判定' ||
                    key === '结果' ||
                    key === '奖惩' ||
                    key === '进度'
                  ) {
                    currentSection[key] = values[0];
                  }
                  if (key === '选项' && Object.keys(currentSection).length > 0) {
                    if (!currentSection.选项数组) {
                      currentSection.选项数组 = [];
                    }
                    currentSection.选项数组.push(values[0]);
                  }
                  if (key === '结束' && Object.keys(currentSection).length > 0) {
                    info.randomEvents.push({ ...currentSection });
                    currentSection = {};
                  }
                  break;
                case '资产':
                  info.inventory.assets[key] = values[0];
                  break;
                case '物品':
                  if (key === '名称') currentSection = {};
                  currentSection[
                    key === '名称'
                      ? 'name'
                      : key === '数量'
                      ? 'quantity'
                      : key === '描述'
                      ? 'description'
                      : key === '效果'
                      ? 'effect'
                      : key
                  ] = key === '数量' ? parseInt(values[0]) : values[0];
                  if (key === '效果') {
                    info.inventory.items.push({ ...currentSection });
                  }
                  break;
                case '债务':
                  info.inventory.debts[key] = values[0];
                  break;
              }
            });

            // 计算社会等级
            calculateSocialLevel(info);

            return info;
          } catch (e) {
            console.error('解析角色信息失败:', e);
            return null;
          }
        },

        extractSocialInfo(text) {
          const match = text.match(/<socialinfo>([\s\S]*?)<\/socialinfo>/);
          if (!match) return null;

          try {
            const relationships = {};
            let currentType = '';
            let currentCharacter = null;

            const lines = match[1]
              .trim()
              .split('\n')
              .filter(line => !line.trim().startsWith('<!--') && line.trim() !== '');

            lines.forEach(line => {
              const [category, key, value, effect] = line.split('|').map(s => s.trim());

              if (category === '关系类型') {
                if (currentCharacter && currentType) {
                  if (!relationships[currentType]) {
                    relationships[currentType] = [];
                  }
                  relationships[currentType].push(currentCharacter);
                }
                currentType = key;
                currentCharacter = null;
              } else if (category === '关系人物') {
                currentCharacter = {
                  name: key,
                  details: {
                    interactions: [],
                    relations: [],
                    basic: {},
                  },
                  // 确保所有人物都有好感度属性，默认为0
                  favor: 0,
                };
              } else if (currentCharacter) {
                switch (category) {
                  case '人物序号':
                    currentCharacter.index = parseInt(key);
                    break;
                  case '态度':
                    // 记录原始态度，但将在显示时根据好感度计算
                    currentCharacter.originalAttitude = key;
                    break;
                  case '好感度':
                    // 确保好感度在-100到+100范围内
                    currentCharacter.favor = Math.max(-100, Math.min(100, parseInt(key)));
                    break;
                  case '身份':
                    currentCharacter.title = key;
                    break;
                  case '状态':
                    currentCharacter.status = key;
                    break;
                  case '描述':
                    currentCharacter.description = key;
                    break;
                  case '人物关系':
                    try {
                      if (key && value) {
                        currentCharacter.details.relations.push({
                          name: key,
                          description: value,
                        });
                      }
                    } catch (e) {
                      console.error('解析NPC关系JSON时出错:', e);
                    }
                    break;
                  case '基本信息':
                    currentCharacter.details.basic[key] = value;
                    break;
                  case '互动记录':
                    if (currentCharacter.details.interactions.length < 3) {
                      const [date, content] = key.split(':');
                      currentCharacter.details.interactions.push({
                        date: date ? date.trim() : '',
                        content: content ? content.trim() : key,
                      });
                    }
                    break;
                }
              }
            });

            // 添加最后一个角色
            if (currentCharacter && currentType) {
              if (!relationships[currentType]) {
                relationships[currentType] = [];
              }
              relationships[currentType].push(currentCharacter);
            }

            // 计算每个角色的态度
            Object.values(relationships).forEach(characters => {
              characters.forEach(character => {
                // 基于好感度动态计算态度
                character.attitude = calculateAttitudeFromFavor(character.favor);
              });
            });

            return relationships;
          } catch (e) {
            console.error('解析社交信息失败:', e);
            return null;
          }
        },

        extractTimelineInfo(text) {
          const match = text.match(/<timelineinfo>([\s\S]*?)<\/timelineinfo>/);
          if (!match) return null;

          try {
            const events = [];
            let currentEvent = {};
            let eventIndex = 0;

            const lines = match[1].trim().split('\n');
            lines.forEach(line => {
              const [category, key, value] = line.split('|').map(s => s.trim());

              if (category.startsWith('事件')) {
                if (key === '日期') {
                  if (Object.keys(currentEvent).length > 0) {
                    events.push({ ...currentEvent });
                  }
                  eventIndex++;
                  currentEvent = {
                    index: eventIndex,
                  };
                }

                switch (key) {
                  case '日期':
                    currentEvent.date = value;
                    break;
                  case '标题':
                    currentEvent.title = value;
                    break;
                  case '描述':
                    currentEvent.description = value;
                    break;
                  case '当前':
                    currentEvent.current = value === 'true';
                    break;
                }
              }
            });

            // 确保添加最后一个事件
            if (Object.keys(currentEvent).length > 0) {
              events.push(currentEvent);
            }

            return events;
          } catch (e) {
            console.error('解析关键节点失败:', e);
            return null;
          }
        },

        extractSectInfo(text) {
          const match = text.match(/<sectinfo>([\s\S]*?)<\/sectinfo>/);
          if (!match) return null;

          try {
            const organizations = {
              official: [],
              civilian: [],
            };

            let currentType = '';
            let currentOrg = null;

            const lines = match[1].trim().split('\n');
            lines.forEach(line => {
              const [category, ...values] = line.split('|').map(s => s.trim());

              switch (category) {
                case '官方组织':
                  if (currentOrg && values[0] === '名称') {
                    if (!organizations.official) organizations.official = [];
                    organizations.official.push({ ...currentOrg });
                  }
                  if (values[0] === '名称') {
                    currentOrg = {
                      name: values[1],
                      members: [],
                    };
                  } else if (currentOrg) {
                    if (values[0] === '类型') {
                      currentOrg.type = values[1];
                    } else if (values[0] === '描述') {
                      currentOrg.description = values[1];
                    } else if (values[0] === '影响力') {
                      currentOrg.influence = parseInt(values[1]);
                    } else if (values[0] === '态度') {
                      currentOrg.attitude = values[1];
                    } else if (values[0] === '成员') {
                      try {
                        // 尝试将成员信息添加到组织中
                        if (values[1] && values[2]) {
                          currentOrg.members.push({
                            name: values[1],
                            position: values[2],
                          });
                        }
                      } catch (e) {
                        console.error('解析组织成员信息失败:', e);
                      }
                    }
                  }
                  break;
                case '民间组织':
                  if (currentOrg && values[0] === '名称') {
                    if (!organizations.civilian) organizations.civilian = [];
                    organizations.civilian.push({ ...currentOrg });
                  }
                  if (values[0] === '名称') {
                    currentOrg = {
                      name: values[1],
                      members: [],
                    };
                  } else if (currentOrg) {
                    if (values[0] === '类型') {
                      currentOrg.type = values[1];
                    } else if (values[0] === '描述') {
                      currentOrg.description = values[1];
                    } else if (values[0] === '影响力') {
                      currentOrg.influence = parseInt(values[1]);
                    } else if (values[0] === '态度') {
                      currentOrg.attitude = values[1];
                    } else if (values[0] === '成员') {
