                        if (values[1] && values[2]) {
                          currentOrg.members.push({
                            name: values[1],
                            position: values[2],
                          });
                        }
                      } catch (e) {
                        console.error('解析组织成员信息失败:', e);
                      }
                    }
                  }
                  break;
              }
            });

            // 确保添加最后一个组织
            if (currentOrg) {
              if (currentType === '官方组织') {
                if (!organizations.official) organizations.official = [];
                organizations.official.push(currentOrg);
              } else if (currentType === '民间组织') {
                if (!organizations.civilian) organizations.civilian = [];
                organizations.civilian.push(currentOrg);
              }
            }

            return organizations;
          } catch (e) {
            console.error('解析组织信息失败:', e);
