      // ==================== 图形绘制模块 ====================
      const GraphicsRenderer = {
        drawAttributesRadarChart(attributes) {
          const canvas = document.getElementById('attributesChart');
          if (!canvas || !attributes) return;

          const ctx = canvas.getContext('2d');
          const centerX = canvas.width / 2;
          const centerY = canvas.height / 2;
          const radius = 120;

          // 清空画布
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          // 获取属性数据并归一化
          const attributeNames = Object.keys(attributes).filter(key => !key.includes('描述'));
          const attributeValues = attributeNames.map(name => attributes[name]);
          const sides = attributeNames.length;

          // 找出最大值用于归一化
          const maxValue = Math.max(...attributeValues, 100);

          // 绘制背景网格
          for (let gridLevel = 1; gridLevel <= 5; gridLevel++) {
            ctx.beginPath();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.1)';

            for (let i = 0; i < sides; i++) {
              const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;
              const r = (radius * gridLevel) / 5;
              const x = centerX + r * Math.cos(angle);
              const y = centerY + r * Math.sin(angle);

              if (i === 0) {
                ctx.moveTo(x, y);
              } else {
                ctx.lineTo(x, y);
              }
            }

            ctx.closePath();
            ctx.stroke();

            // 添加刻度值标注
            const scaleValue = Math.round((maxValue * gridLevel) / 5);
            ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
            ctx.font = '12px var(--global-font)';
            ctx.fillText(scaleValue.toString(), centerX + 5, centerY - (radius * gridLevel) / 5);
          }

          // 绘制属性轴线和名称
          for (let i = 0; i < sides; i++) {
            const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;

            // 绘制轴线
            ctx.beginPath();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.2)';
            ctx.moveTo(centerX, centerY);
            ctx.lineTo(centerX + radius * Math.cos(angle), centerY + radius * Math.sin(angle));
            ctx.stroke();

            // 绘制属性名称
            ctx.fillStyle = '#333';
            ctx.font = '14px var(--global-font)';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';

            const textRadius = radius + 20;
            const textX = centerX + textRadius * Math.cos(angle);
            const textY = centerY + textRadius * Math.sin(angle);

            ctx.fillText(`${attributeNames[i]} (${attributeValues[i]})`, textX, textY);
          }

          // 绘制数值区域
          ctx.beginPath();
          ctx.fillStyle = 'rgba(139, 69, 19, 0.2)';
          ctx.strokeStyle = 'rgba(139, 69, 19, 0.8)';
          ctx.lineWidth = 2;

          for (let i = 0; i < sides; i++) {
            const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;
            const normalizedValue = attributeValues[i] / maxValue;
            const r = radius * normalizedValue;
            const x = centerX + r * Math.cos(angle);
            const y = centerY + r * Math.sin(angle);

            if (i === 0) {
              ctx.moveTo(x, y);
            } else {
              ctx.lineTo(x, y);
            }
          }

          ctx.closePath();
          ctx.fill();
          ctx.stroke();

          // 绘制数值点
          for (let i = 0; i < sides; i++) {
            const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;
            const normalizedValue = attributeValues[i] / maxValue;
            const r = radius * normalizedValue;
            const x = centerX + r * Math.cos(angle);
            const y = centerY + r * Math.sin(angle);

            ctx.beginPath();
            ctx.fillStyle = '#8B4513';
            ctx.arc(x, y, 4, 0, 2 * Math.PI);
            ctx.fill();
          }
        },

        drawValuesRadarChart(values) {
          const canvas = document.getElementById('valuesRadarChart');
          if (!canvas || !values) return;

          const ctx = canvas.getContext('2d');
          const centerX = canvas.width / 2;
          const centerY = canvas.height / 2;
          const radius = 120;

          // 清空画布
          ctx.clearRect(0, 0, canvas.width, canvas.height);

          // 筛选出欲念和道德属性
          const desireNames = ['权欲', '财欲', '色欲', '名欲'].filter(name => values[name] !== undefined);
          const moralNames = ['仁德', '义气', '礼节', '信誉'].filter(name => values[name] !== undefined);

          const desireValues = desireNames.map(name => values[name]);
          const moralValues = moralNames.map(name => values[name]);

          const sides = desireNames.length + moralNames.length;
          const allNames = [...desireNames, ...moralNames];
          const allValues = [...desireValues, ...moralValues];

          // 找出最大值用于归一化
          const maxValue = Math.max(...allValues, 100);

          // 绘制标题
          ctx.fillStyle = '#333';
          ctx.font = 'bold 16px var(--global-font)';
          ctx.textAlign = 'center';
