            ctx.fillText(scaleValue.toString(), centerX + 5, centerY - (radius * gridLevel) / 5);
          }

          // 绘制属性轴线和名称
          for (let i = 0; i < sides; i++) {
            const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;

            // 绘制轴线
            ctx.beginPath();
            ctx.strokeStyle = 'rgba(0, 0, 0, 0.2)';
            ctx.moveTo(centerX, centerY);
            ctx.lineTo(centerX + radius * Math.cos(angle), centerY + radius * Math.sin(angle));
            ctx.stroke();

            // 绘制属性名称
            ctx.fillStyle = i < desireNames.length ? '#B71C1C' : '#1A5276';
            ctx.font = '14px var(--global-font)';
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';

            const textRadius = radius + 20;
            const textX = centerX + textRadius * Math.cos(angle);
            const textY = centerY + textRadius * Math.sin(angle);

            ctx.fillText(`${allNames[i]} (${allValues[i]})`, textX, textY);
          }

          // 绘制欲念数值区域
          if (desireValues.length > 0) {
            ctx.beginPath();
            ctx.fillStyle = 'rgba(183, 28, 28, 0.2)';
            ctx.strokeStyle = 'rgba(183, 28, 28, 0.8)';
            ctx.lineWidth = 2;

            for (let i = 0; i < desireNames.length; i++) {
              const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;
              const normalizedValue = desireValues[i] / maxValue;
              const r = radius * normalizedValue;
              const x = centerX + r * Math.cos(angle);
              const y = centerY + r * Math.sin(angle);

              if (i === 0) {
                ctx.moveTo(x, y);
              } else {
                ctx.lineTo(x, y);
              }
            }

            ctx.closePath();
            ctx.fill();
            ctx.stroke();

            // 绘制欲念数值点
            for (let i = 0; i < desireNames.length; i++) {
              const angle = (i * 2 * Math.PI) / sides - Math.PI / 2;
              const normalizedValue = desireValues[i] / maxValue;
              const r = radius * normalizedValue;
              const x = centerX + r * Math.cos(angle);
              const y = centerY + r * Math.sin(angle);

              ctx.beginPath();
              ctx.fillStyle = '#B71C1C';
              ctx.arc(x, y, 4, 0, 2 * Math.PI);
              ctx.fill();
            }
          }

          // 绘制道德数值区域
          if (moralValues.length > 0) {
            ctx.beginPath();
            ctx.fillStyle = 'rgba(26, 82, 118, 0.2)';
            ctx.strokeStyle = 'rgba(26, 82, 118, 0.8)';
            ctx.lineWidth = 2;

            for (let i = 0; i < moralNames.length; i++) {
              const idx = i + desireNames.length;
              const angle = (idx * 2 * Math.PI) / sides - Math.PI / 2;
              const normalizedValue = moralValues[i] / maxValue;
              const r = radius * normalizedValue;
              const x = centerX + r * Math.cos(angle);
              const y = centerY + r * Math.sin(angle);

              if (i === 0) {
                ctx.moveTo(x, y);
              } else {
                ctx.lineTo(x, y);
              }
            }

            ctx.closePath();
            ctx.fill();
            ctx.stroke();

            // 绘制道德数值点
            for (let i = 0; i < moralNames.length; i++) {
              const idx = i + desireNames.length;
              const angle = (idx * 2 * Math.PI) / sides - Math.PI / 2;
              const normalizedValue = moralValues[i] / maxValue;
              const r = radius * normalizedValue;
              const x = centerX + r * Math.cos(angle);
              const y = centerY + r * Math.sin(angle);

              ctx.beginPath();
              ctx.fillStyle = '#1A5276';
              ctx.arc(x, y, 4, 0, 2 * Math.PI);
              ctx.fill();
            }
          }

          // 添加图例
          const legendY = canvas.height - 30;

          // 欲念图例
          ctx.beginPath();
          ctx.fillStyle = 'rgba(183, 28, 28, 0.2)';
          ctx.strokeStyle = 'rgba(183, 28, 28, 0.8)';
          ctx.lineWidth = 1;
          ctx.rect(centerX - 100, legendY, 15, 15);
          ctx.fill();
          ctx.stroke();

          ctx.fillStyle = '#333';
          ctx.textAlign = 'left';
          ctx.font = '14px var(--global-font)';
          ctx.fillText('欲念', centerX - 80, legendY + 12);

          // 道德图例
          ctx.beginPath();
          ctx.fillStyle = 'rgba(26, 82, 118, 0.2)';
          ctx.strokeStyle = 'rgba(26, 82, 118, 0.8)';
          ctx.lineWidth = 1;
          ctx.rect(centerX + 20, legendY, 15, 15);
          ctx.fill();
          ctx.stroke();

          ctx.fillStyle = '#333';
          ctx.textAlign = 'left';
          ctx.font = '14px var(--global-font)';
          ctx.fillText('道德', centerX + 40, legendY + 12);
