      let archiveSaved = false;

      // 完全重写applyTaskReward函数，使用更可靠的方式查找和更新DOM元素
      function applyTaskReward(rewardText, characterInfo) {
        // 解析奖励文本，格式通常为"属性名+数值"，如"武力+5，智力+3"
        const rewards = rewardText.split('，'); // 使用中文逗号分割

        rewards.forEach(reward => {
          // 尝试匹配"属性名+数值"的模式
          const match = reward.match(/(.+?)([+-]\d+)/);
          if (match) {
            const attributeName = match[1].trim();
            const changeValue = parseInt(match[2]);

            // 更新对应的属性值
            if (characterInfo.attributes[attributeName] !== undefined) {
              // 更新数据模型
              characterInfo.attributes[attributeName] += changeValue;

              // 直接通过遍历DOM元素查找匹配的属性名元素，避免使用自定义选择器
              const attributeItems = document.querySelectorAll('.attribute-item');
              attributeItems.forEach(item => {
                const nameElement = item.querySelector('.attribute-name');
                if (nameElement && nameElement.textContent === attributeName) {
                  const valueElement = item.querySelector('.attribute-value');
                  if (valueElement) {
                    // 更新DOM显示
                    valueElement.textContent = characterInfo.attributes[attributeName];
                  }
                }
              });
            }
            // 更新values中的值（如欲念、道德等）
            else if (characterInfo.values[attributeName] !== undefined) {
              characterInfo.values[attributeName] += changeValue;
            }
          }
        });

        // 重绘属性雷达图以反映变化
        if (window.GraphicsRenderer) {
          GraphicsRenderer.drawAttributesRadarChart(characterInfo.attributes);
          GraphicsRenderer.drawValuesRadarChart(characterInfo.values);
        }
      }

      // 添加计算社会等级的函数
      function calculateSocialLevel(characterInfo) {
        if (!characterInfo || !characterInfo.attributes) return;

        // 计算所有属性的平均值
        const attributeValues = Object.entries(characterInfo.attributes)
          .filter(([key]) => !key.includes('描述'))
          .map(([_, value]) => value);

        const averageAttribute =
          attributeValues.length > 0
            ? attributeValues.reduce((sum, value) => sum + value, 0) / attributeValues.length
            : 0;

        // 根据平均属性值确定社会等级
        let socialLevel = 1;
        if (averageAttribute >= 90) socialLevel = 8;
        else if (averageAttribute >= 60) socialLevel = 7;
        else if (averageAttribute >= 40) socialLevel = 6;
        else if (averageAttribute >= 27) socialLevel = 5;
        else if (averageAttribute >= 18) socialLevel = 4;
        else if (averageAttribute >= 12) socialLevel = 3;
        else if (averageAttribute >= 8) socialLevel = 2;

        // 存储社会等级
        characterInfo.socialLevel = socialLevel;
        characterInfo.averageAttribute = Math.round(averageAttribute * 10) / 10; // 保留一位小数

        return socialLevel;
      }

      // 添加基于好感度计算态度的函数
      function calculateAttitudeFromFavor(favor) {
        // 确保好感度在-100到+100范围内
        const normalizedFavor = Math.max(-100, Math.min(100, favor));

        // 根据好感度范围确定态度
        if (normalizedFavor <= -70) return '深仇大恨';
        if (normalizedFavor <= -40) return '敌对';
        if (normalizedFavor <= -10) return '不友好';
        if (normalizedFavor < 10) return '中立';
        if (normalizedFavor < 40) return '友善';
        if (normalizedFavor < 70) return '信任';
        return '亲密';
      }

      // 添加获取态度对应CSS类的函数
      function getAttitudeClass(attitude) {
        switch (attitude) {
          case '深仇大恨':
            return 'attitude-hostile';
          case '敌对':
            return 'attitude-hostile';
          case '不友好':
            return 'attitude-unfriendly';
          case '中立':
            return 'attitude-neutral';
          case '友善':
            return 'attitude-friendly';
          case '信任':
            return 'attitude-trusted';
          case '亲密':
            return 'attitude-devoted';
          default:
            return 'attitude-neutral';
        }
      }
      // 添加判断是否有随机事件的函数
      function hasRandomEvent(info) {
        // 检查是否有随机事件数据
        if (!info.randomEvents || info.randomEvents.length === 0) {
          return false;
        }
        // 随机生成一个概率（30%几率触发）
        return Math.random() < 0.3 ? true : false;
      }
    </script>
