        // 初始化开始游戏按钮
        function initializeStartGameButton() {
          document.getElementById('start-game').addEventListener('click', function () {
            // 计算最终属性值
            calculateFinalAttributes();

            // 基础游戏数据
            const characterData = {
              gender: gameData.player.gender,
              identity: gameData.player.identity,
              identityName: getIdentityName(gameData.player.identity),
              experience: gameData.player.experience,
              skill: gameData.player.skill,
              attributes: gameData.player.attributes,
              desires: gameData.player.desires,
              morals: gameData.player.morals,
            };

            // 构建角色信息文本
            const characterInfo = buildCharacterInfo(characterData);

            // 生成命令序列
            const commands = [
              // 设置基本属性
              ...Object.entries(characterData.attributes).map(([attr, value]) => `/setvar key=${attr} ${value}`),

              // 设置欲念和道德
              ...Object.entries(characterData.desires).map(([desire, value]) => `/setvar key=${desire} ${value}`),
              ...Object.entries(characterData.morals).map(([moral, value]) => `/setvar key=${moral} ${value}`),

              // 设置基本信息
              `/setvar key=gender ${characterData.gender === 'male' ? '男' : '女'}`,
              `/setvar key=identity ${characterData.identityName}`,
              `/setvar key=experience ${characterData.experience}`,
              `/setvar key=skill ${characterData.skill}`,

              // 保存角色信息和启动游戏
              `/createentry file=chatLore key=角色信息 ${characterInfo}`,
              `/send ${characterInfo}`,
              `/trigger`,
            ];

            // 执行命令
            try {
              // 检查triggerSlash函数是否可用
              if (typeof window.triggerSlash === 'function') {
                window.triggerSlash(commands.join('|'));
              } else {
                console.log('命令已生成，但triggerSlash函数不可用');
                alert('角色创建完成，游戏即将开始！\n\n由于环境限制，无法直接启动游戏。');
              }
            } catch (e) {
              console.error('执行命令时出错:', e);
              alert('启动游戏时发生错误，请查看控制台了解详情。');
            }
          });
        }

        // 计算最终属性值
        function calculateFinalAttributes() {
          // 重置属性为用户设置的基础值
          const baseAttributes = { ...gameData.player.attributes };
          const baseDesires = { 权欲: 10, 财欲: 10, 色欲: 10, 名欲: 10 };
          const baseMorals = { 仁德: 0, 义气: 0, 礼节: 0, 信誉: 0 };

          // 设置身份属性 - 这里是直接赋值而不是增加
          if (gameData.player.identity && identityAttributes[gameData.player.identity]) {
            Object.entries(identityAttributes[gameData.player.identity]).forEach(([attr, value]) => {
              if (baseAttributes[attr] !== undefined) {
                // 这里不是增加，而是直接设置基础值
                baseAttributes[attr] = value;
              }
            });
          }

          // 设置身份的欲念和道德值 - 这里是直接赋值而不是增加
          if (gameData.player.identity && identityValues[gameData.player.identity]) {
            Object.entries(identityValues[gameData.player.identity]).forEach(([key, value]) => {
              if (baseDesires[key] !== undefined) {
                baseDesires[key] = value;
              } else if (baseMorals[key] !== undefined) {
                baseMorals[key] = value;
              }
            });
          }

          // 应用经历对属性的影响 - 这些是增量修改
          if (gameData.player.experience && experienceEffects[gameData.player.experience]) {
            Object.entries(experienceEffects[gameData.player.experience]).forEach(([key, value]) => {
              if (baseAttributes[key] !== undefined) {
                baseAttributes[key] += value;
              } else if (baseDesires[key] !== undefined) {
                baseDesires[key] += value;
              } else if (baseMorals[key] !== undefined) {
                baseMorals[key] += value;
              }
            });
          }

          // 应用特长对属性的影响 - 这些是增量修改
          if (gameData.player.skill && skillEffects[gameData.player.skill]) {
            Object.entries(skillEffects[gameData.player.skill]).forEach(([key, value]) => {
              if (baseAttributes[key] !== undefined) {
                baseAttributes[key] += value;
              } else if (baseDesires[key] !== undefined) {
                baseDesires[key] += value;
              } else if (baseMorals[key] !== undefined) {
                baseMorals[key] += value;
              }
            });
          }

          // 确保基础属性值在有效范围内 (0-30)
          Object.keys(baseAttributes).forEach(attr => {
            baseAttributes[attr] = Math.max(0, Math.min(baseAttributes[attr], 30));
          });

          // 确保欲念值在有效范围内 (0-30)
          Object.keys(baseDesires).forEach(desire => {
            baseDesires[desire] = Math.max(0, Math.min(baseDesires[desire], 30));
          });

          // 道德值可以为负数，但限制在-20到20之间
          Object.keys(baseMorals).forEach(moral => {
            baseMorals[moral] = Math.max(-20, Math.min(baseMorals[moral], 20));
          });

          // 更新游戏数据
          gameData.player.attributes = baseAttributes;
          gameData.player.desires = baseDesires;
          gameData.player.morals = baseMorals;

          console.log('最终属性计算完成', gameData.player);
        }

