          if (!effectElement) return;

          const titleElement = effectElement.querySelector('.effect-title');
          const contentElement = effectElement.querySelector('.effect-content');

          if (!selected) {
            contentElement.textContent = `未选择${
              type === 'identity' ? '身份' : type === 'experience' ? '经历' : '特长'
            }`;
            return;
