            const attrEffects = [];

            Object.entries(effectsObj[selected]).forEach(([attr, value]) => {
              attrEffects.push(`${attr} ${value}`);
            });

            if (attrEffects.length > 0) {
              effectsText += `基础属性：${attrEffects.join('，')}`;
