          });

          // 道德值可以为负数，但限制在-20到20之间
          Object.keys(previewMorals).forEach(moral => {
            previewMorals[moral] = Math.max(-20, Math.min(previewMorals[moral], 20));
          });

          return {
            attributes: previewAttributes,
            desires: previewDesires,
            morals: previewMorals,
          };
        }
      });
    </script>
  </body>
